CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS "SoundLabsLiveSession"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"projectId" TEXT NOT NULL REFERENCES "SoundLabsProject"("id") ON DELETE CASCADE,"ownerId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"crowdMode" TEXT NOT NULL DEFAULT 'GUIDED',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "SoundLabsLiveParticipant"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"sessionId" TEXT NOT NULL REFERENCES "SoundLabsLiveSession"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" TEXT NOT NULL DEFAULT 'VIEWER',"presence" TEXT NOT NULL DEFAULT 'offline',"joinedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"lastSeenAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("sessionId","userId"));
CREATE TABLE IF NOT EXISTS "SoundLabsLiveMessage"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"sessionId" TEXT NOT NULL REFERENCES "SoundLabsLiveSession"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"text" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "SoundLabsLiveSession_owner_idx" ON "SoundLabsLiveSession"("ownerId");
CREATE INDEX IF NOT EXISTS "SoundLabsLiveParticipant_session_idx" ON "SoundLabsLiveParticipant"("sessionId");
CREATE INDEX IF NOT EXISTS "SoundLabsLiveMessage_session_idx" ON "SoundLabsLiveMessage"("sessionId","createdAt");
